'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>n==null?'Unknown':n>=1e12?(n/1e12).toFixed(1)+' TB':n>=1e9?(n/1e9).toFixed(1)+' GB':n>=1e6?(n/1e6).toFixed(1)+' MB':n>=1e3?(n/1e3).toFixed(1)+' KB':n+' B';
const names={e2:'IDrive E2',cloudgate:'CloudGate',linux:'Linux',windows:'Windows'};
const colors={audio:'#b39aff',video:'#f5b86c',images:'#66b8ee',text:'#75cfac',code:'#f58da0',other:'#8795aa'};
const S={data:null,host:null,nav:'groups',group:null,tab:'storage',search:'',modal:null,draft:{},busy:false};
let toastTimer;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),6500)}
async function api(path,body){const r=await fetch(path.replace(/^\//,''),{method:body===undefined?'GET':'POST',headers:{'Content-Type':'application/json','X-Robo-Request':'1'},...(body===undefined?{}:{body:JSON.stringify(body)})});const data=await r.json();if(!r.ok)throw Error(data.error||'Request failed');return data}
function icon(kind){return `<span class="provider-icon"><img src="assets/${esc(kind)}.svg" alt="${esc(names[kind])}"></span>`}
function activeServers(gid){return S.data.servers.filter(s=>s.status!=='removed'&&(!gid||s.group===gid))}
function group(id){return S.data.groups.find(g=>g.id===id)}
function server(id){return S.data.servers.find(s=>s.id===id)}
function total(list,key){return list.reduce((v,s)=>v+(Number(s[key])||0),0)}
function cap(s){if(Number.isFinite(s.allocatedCapacity))return s.allocatedCapacity;const limit=Number(s.limit)||0,physical=Number(s.capacity)||0;return limit&&physical?Math.min(limit,physical):limit||physical}
function capacity(list){return list.reduce((n,s)=>n+cap(s),0)}
function partitionCap(s,p){const ceilings=[cap(s),p.limit,...s.partitions.filter(a=>a!==p&&p.path.startsWith(a.path+'/')).map(a=>a.limit)].filter(n=>n>0);return ceilings.length?Math.min(...ceilings):0}
function percent(s){return cap(s)?Math.min(100,s.used/cap(s)*100):0}
function usageSegments(s){const c=Math.max(cap(s),Number(s.used)||0,1);return Object.entries(s.types||{}).filter(([,v])=>v>0).map(([k,v])=>`<span class="usage-segment" style="width:${Math.min(v/c*100,100)}%;background:${colors[k]||colors.other}" title="${esc(k)} · ${fmt(v)}"></span>`).join('')}
function segments(s){return `<div class="meter">${usageSegments(s)}</div>`}
function usageBar(s){return `<div class="big-bar small-bar usage-bar" aria-label="${esc(fmt(s.used)+' used of '+(cap(s)?fmt(cap(s)):'unknown capacity'))}">${usageSegments(s)}<span class="usage-caption"><strong>${fmt(s.used)} used · ${cap(s)?fmt(Math.max(cap(s)-s.used,0))+' free':'capacity unknown'}</strong><small>${esc(s.error||(s.status==='draining'?'Uploads blocked · draining':s.readOnly?'Read-only mode':s.limit&&s.used>=s.limit?'Full · uploads blocked':'Quota-enforced uploads'))}</small></span></div>`}
function copyIcon(copied=false){return `<svg viewBox="0 0 16 16" width="16" height="16" fill="currentColor" aria-hidden="true">${copied?'<path d="M13.8 3.5a.75.75 0 0 1 0 1.06l-7.5 7.5a.75.75 0 0 1-1.06 0L2.2 9.03a.75.75 0 1 1 1.06-1.06l2.51 2.5 6.97-6.97a.75.75 0 0 1 1.06 0Z"/>':'<path d="M0 6.75C0 5.78.78 5 1.75 5H3v1.5H1.75a.25.25 0 0 0-.25.25v7.5c0 .14.11.25.25.25h7.5a.25.25 0 0 0 .25-.25V13H11v1.25c0 .97-.78 1.75-1.75 1.75h-7.5A1.75 1.75 0 0 1 0 14.25Z"/><path d="M5 1.75C5 .78 5.78 0 6.75 0h7.5C15.22 0 16 .78 16 1.75v7.5c0 .97-.78 1.75-1.75 1.75h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .14.11.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"/>'}</svg>`}

function address(g){if(g.url)return g.url.replace(/^https?:\/\//,'');if(g.proposedUrl)return g.proposedUrl.replace(/^https?:\/\//,'')+' · checking';const chosen=g.base||g.domain,base=g.useDefaultTunnel===false?((S.host?.domains||[]).includes(chosen)?chosen:''):(g.resolvedBase||S.host?.base);return base?`${g.sub}.${base}`:'Burrow assigns the group HTTPS address'}
function statePill(s){const online=s.status==='online'&&s.online!==false;return `<span class="server-status ${online?'':'warn'}">${online?'● Connected':s.status==='draining'?'◌ Draining':s.status==='full'?'● Full':s.verified?'○ Offline':'× Not verified'}</span>`}
function legend(){return `<div class="legend">${Object.entries(colors).map(([k,v])=>`<span><i style="background:${v}"></i>${k[0].toUpperCase()+k.slice(1)}</span>`).join('')}</div>`}
function demoNotice(){return S.data.demo?'<div class="notice"><span class="pill demo">DEMO WORKSPACE</span>Example usage and addresses, not connected storage. No real tunnels, tests, migration or erasure run here.</div>':''}
function agentRouteNote(){return S.data.demo?'Burrow automatically prepares the HTTPS enrollment address on an installed host. Live enrollment is disabled in this demo.':S.data.agentRoute?.state==='ready'?'HTTPS enrollment is ready. Burrow configured and checked the address automatically.':S.data.agentRoute?.detail||'Burrow is preparing the HTTPS enrollment address automatically. No manual base URL is needed.'}
function head(eyebrow,title,sub,action=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtitle">${sub}</p></div>${action}</div>`}
function statistics(){const ss=activeServers(),limit=capacity(ss),used=total(ss,'used');return `<div class="stats"><div class="stat card"><div class="stat-top"><span>Storage used</span><span>◴</span></div><div class="stat-value">${fmt(used).replace(/ (\w+)$/,' <small>$1</small>')}</div><div class="stat-foot">${limit?`${Math.round(used/limit*100)}% of ${fmt(limit)} allocated storage`:'No capacity limit configured'}</div></div><div class="stat card"><div class="stat-top"><span>Total allocation</span><span>▤</span></div><div class="stat-value">${fmt(limit||null).replace(/ (\w+)$/,' <small>$1</small>')}</div><div class="stat-foot">${ss.filter(s=>!cap(s)).length?'Some server capacities are unknown':'Across your connected storage'}</div></div><div class="stat card"><div class="stat-top"><span>Storage servers</span><span>▧</span></div><div class="stat-value">${ss.length}<small> / ${S.data.groups.length} groups</small></div><div class="stat-foot"><span class="green">${ss.filter(s=>s.verified&&s.online!==false).length} verified</span> · ${new Set(ss.map(s=>s.kind)).size} storage providers</div></div><div class="stat card"><div class="stat-top"><span>Group users</span><span>♙</span></div><div class="stat-value">${S.data.users.filter(u=>u.enabled).length}<small> active</small></div><div class="stat-foot">Directory-level access controls</div></div></div>`}
function serverRow(s,detail=false){return `<div class="server-row">${icon(s.kind)}<div class="grow"><div class="server-name">${esc(s.name)}</div>${s.url?`<a class="server-link" href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.url.replace(/^https?:\/\//,''))} ↗</a>`:`<span class="server-link">${['linux','windows'].includes(s.kind)?esc(s.path||'Choose a folder during installation'):'Not published'}</span>`}${segments(s)}<div class="capacity-label"><span>${fmt(s.used)} <span class="faint">of ${cap(s)?fmt(cap(s)):'no configured limit'}</span></span><span>${cap(s)?Math.round(percent(s))+'%':'—'}</span></div></div><div class="server-actions">${statePill(s)}<div class="row" style="gap:5px"><button class="btn small ghost" data-act="test" data-id="${s.id}">↻ Test</button>${detail?`<button class="icon-btn" data-act="server-settings" data-id="${s.id}" aria-label="Settings for ${esc(s.name)}">⋯</button>`:''}</div></div></div>`}
function groupCard(g){const ss=activeServers(g.id),used=total(ss,'used'),limit=capacity(ss),users=S.data.users.filter(u=>u.group===g.id&&u.enabled).length;return `<article class="group-card card"><div class="group-head"><span class="folder-icon">▱</span><div><div class="group-title">${esc(g.name)}</div><div class="group-address">${esc(address(g))}</div></div><span class="pill ${g.url?'good':''}">${ss.length} server${ss.length===1?'':'s'}</span></div><div class="group-capacity"><div class="capacity-label"><span><strong>${fmt(used)}</strong> used</span><span>${limit?fmt(limit)+' allocated':'No allocated storage'}</span></div><div class="meter">${ss.map((s,i)=>`<span title="${esc(s.name)}: ${fmt(s.used)}" style="width:${limit?Math.min(100,s.used/limit*100):0}%;background:${['#8bdfbf','#a594d2','#7ca9d0'][i%3]}"></span>`).join('')}</div></div><div class="server-list">${ss.slice(0,3).map(s=>serverRow(s)).join('')||'<div class="empty" style="padding:26px">No servers yet. Connect your first storage provider.</div>'}${ss.length>3?`<button class="text-btn" data-act="open-group" data-id="${g.id}">View ${ss.length-3} more servers →</button>`:''}</div><div class="group-foot"><span class="foot-meta">♙ ${users} user${users===1?'':'s'} <span style="margin:0 6px">·</span> ${ss.filter(s=>s.verified).length} verified</span><div class="row"><button class="text-btn" data-act="add-server" data-id="${g.id}">＋ Add Server</button><button class="btn small" data-act="open-group" data-id="${g.id}">Open ↗</button></div></div></article>`}
function renderGroups(){return head('YOUR CONNECTED STORAGE','Server groups','Bring your storage together. Keep everything under your control.','<button class="btn primary" data-act="add-group"><span>＋</span> Add Server Group</button>')+demoNotice()+statistics()+`<div class="toolbar"><div class="section-title"><h2>Your groups</h2><span>${S.data.groups.length} groups</span></div><label class="search">⌕ <input id="group-search" placeholder="Search groups…" value="${esc(S.search)}" aria-label="Search groups"></label></div><div class="group-grid" id="group-grid">${groupCards()}</div><div class="hint-row"><span>ⓘ</span><span>One group. Multiple providers. <b>A single place for your files.</b></span></div>`}
function groupCards(){return S.data.groups.filter(g=>g.name.toLowerCase().includes(S.search.toLowerCase())).map(groupCard).join('')+`<button class="add-card" data-act="add-group"><span class="plus">＋</span><strong>Make room for more</strong><p>Create a group to connect servers and organize your next project.</p><span class="text-btn">Add Server Group →</span></button>`}
function groupView(){const g=group(S.group),ss=activeServers(g.id),limit=capacity(ss);return `<button class="back" data-act="back">← All server groups</button>`+head('SERVER GROUP',esc(g.name),esc(address(g)),`<button class="btn primary" data-act="add-server" data-id="${g.id}"><span>＋</span> Add Server</button>`)+demoNotice()+`<div class="local-tabs" role="tablist">${['storage','users','routing','activity'].map(t=>`<button role="tab" aria-selected="${S.tab===t}" class="${S.tab===t?'active':''}" data-act="group-tab" data-tab="${t}">${({storage:'Storage & partitions',users:'Users & access',routing:'Domains & routing',activity:'Activity'})[t]}</button>`).join('')}</div>`+(S.tab==='storage'?`<section class="panel card"><div class="panel-title"><div><h2>Storage distribution</h2><p class="subtitle">${fmt(total(ss,'used'))} used across ${limit?fmt(limit):'unknown total capacity'}</p></div><span class="pill">${ss.length} servers</span></div><div class="big-bar">${ss.map((s,i)=>`<div class="bar-section" style="flex:0 0 ${limit?cap(s)/limit*100:100/Math.max(ss.length,1)}%;--segment:${Object.values(colors)[i%6]};${limit&&!cap(s)?'display:none;':''}" title="${esc(s.name)} contributes ${limit?Math.round(cap(s)/limit*100):0}% of allocated storage"><span class="bar-used" style="width:${percent(s)}%"></span><span class="bar-caption"><strong>${esc(s.name)}</strong><small>${cap(s)?fmt(cap(s)):'Unknown capacity'}</small><small>${fmt(s.used)} used</small></span></div>`).join('')||'<div class="empty grow">Add a server to see the storage distribution.</div>'}</div>${legend()}<p class="form-hint">Segment widths represent allocated storage. Hover to reveal each server’s color. File-type colors below reflect the latest inventory.</p></section><div class="toolbar"><h2>Servers in this group</h2><span class="faint" style="font-size:10px">Refresh usage with Test</span></div>${ss.map(s=>`<section class="panel card server-detail"><div class="server-detail-head">${icon(s.kind)}<div class="grow"><h3>${esc(s.name)}</h3><p class="form-hint">${names[s.kind]} · ${s.allocationLimit?'Allocation ceiling '+fmt(s.allocationLimit)+' · ':''}${s.physicalCapacity?'Physical capacity '+fmt(s.physicalCapacity)+' · ':''}${s.lastTest?'Last inventory '+new Date(s.lastTest*1000).toLocaleString():'Not tested'}</p></div>${statePill(s)}<button class="btn small ghost" data-act="test" data-id="${s.id}">↻ Test</button><button class="icon-btn" data-act="server-settings" data-id="${s.id}" aria-label="Server options">⋯</button></div>${usageBar(s)}${[...s.partitions].sort((a,b)=>a.path.localeCompare(b.path)).map(p=>{const used=s.inventory.filter(f=>f.path===p.path||f.path.startsWith(p.path+'/')).reduce((n,f)=>n+f.size,0);return `<div class="partition" style="margin-left:${Math.min(45,15*(1+s.partitions.filter(x=>p.path.startsWith(x.path+'/')).length))}%"><div class="partition-head"><strong>↳ ${esc(p.name)}</strong><span>${fmt(used)} / ${partitionCap(s,p)?fmt(partitionCap(s,p))+(p.limit?'':' inherited'):'unknown capacity'}</span></div><p class="mono">${esc(p.path)}/</p><div class="meter" style="margin-top:10px"><span style="width:${partitionCap(s,p)?Math.min(used/partitionCap(s,p)*100,100):0}%"></span></div></div>`}).join('')}${s.url?`<a class="text-btn" href="${esc(s.url)}" target="_blank" rel="noopener">Open storage ↗</a>`:''}</section>`).join('')}`:S.tab==='users'?usersView(g.id):S.tab==='routing'?routingView(g):activityView(g.id))}
function usersView(gid){const users=S.data.users.filter(u=>!gid||u.group===gid);return `<div class="panel card"><div class="panel-title"><div><h2>Users & directory permissions</h2><p class="subtitle">Most-specific path rule wins. Hidden paths stay hidden in the API, too.</p></div><button class="btn primary small" data-act="add-user" data-id="${gid||''}">＋ Add User</button></div><div class="table-wrap"><table><thead><tr><th>USERNAME</th>${!gid?'<th>GROUP</th>':''}<th>ACCESS RULES</th><th>STATUS</th><th></th></tr></thead><tbody>${users.map(u=>`<tr><td><strong>${esc(u.username)}</strong></td>${!gid?`<td>${esc(group(u.group)?.name)}</td>`:''}<td>${u.rules.map(r=>`<div class="mono">${esc(r.path||'/')} <span class="faint">→ ${esc(r.access)}</span></div>`).join('')}</td><td><span class="pill ${u.enabled?'good':''}">${u.enabled?'Active':'Disabled'}</span></td><td><button class="btn small" data-act="edit-user" data-id="${u.id}">Manage</button></td></tr>`).join('')||'<tr><td colspan="5">No users yet. Create a user before publishing the group.</td></tr>'}</tbody></table></div><p class="password-note">⌑ Storage links use the browser’s native username/password dialog (HTTP Basic over HTTPS). Passwords are hashed, never embedded in URLs. Disable a user or rotate their password to revoke future requests.</p></div>`}
function routingView(g){return `<div class="panel card"><div class="panel-title"><div><h2>Group address & tunnel</h2><p class="subtitle">One shared address for this group and all of its servers.</p></div><span id="route-live-badge" class="pill ${g.routeState==='ready'?'good':''}">${g.routeState==='ready'?'HTTPS verified':g.routeState==='blocked'?'Root unavailable':g.routeState==='not-published'?'Not published':'Checking route'}</span></div>${routeFields(g)}<button class="btn primary" data-act="launch-group" data-id="${g.id}">Launch Group ↗</button><div id="route-live-address">${g.url?`<p class="subtitle"><a href="${esc(g.url)}" target="_blank" rel="noopener">${esc(g.url)} ↗</a></p>`:''}</div><p id="route-live-detail" class="form-hint">${esc(g.routeDetail||'Burrow will supply the address. It is marked ready only after an HTTPS identity check succeeds.')}</p>${g.proposedUrl&&!g.url?`<p class="form-hint mono">Proposed: ${esc(g.proposedUrl)}</p>`:''}</div>`}
function activityView(gid){const jobs=S.data.jobs.filter(j=>!gid||server(j.server)?.group===gid);return `<div class="panel card"><h2>Transfer & removal jobs</h2>${jobs.map(j=>`<div class="connection"><span class="pill ${j.state==='done'?'good':j.state==='error'?'danger':'warn'}">${esc(j.state)}</span><div><h3>${esc(server(j.server)?.name)} · ${esc(j.mode)}</h3><p>${esc(j.detail)} · ${j.done}/${j.total} files</p></div></div>`).join('')||'<p class="subtitle">No migration or removal jobs.</p>'}</div><div class="panel card"><h2>Recent activity</h2><div class="table-wrap"><table><thead><tr><th>EVENT</th><th>DETAIL</th><th>TIME</th></tr></thead><tbody>${S.data.audit.slice(0,80).map(a=>`<tr><td><strong>${esc(a.action)}</strong></td><td>${esc(a.detail)}</td><td>${new Date(a.at*1000).toLocaleString()}</td></tr>`).join('')||'<tr><td>No activity yet.</td></tr>'}</tbody></table></div></div>`}
function connectionsView(){return head('INFRASTRUCTURE','Connections','Your storage providers and the Aegis host that brings them together.')+demoNotice()+`<div class="panel card"><div class="connection"><span class="folder-icon">⌘</span><div class="grow"><h2>Aegis × Burrow</h2><p>${esc(S.host?.note||'Burrow control socket is not available.')}</p><p class="mono">Tunnel base: ${esc(S.host?.base||'not configured')}</p></div><span class="pill ${S.host?.connected?'good':'warn'}">${S.host?.connected?'Connected':'Not connected'}</span></div>${Object.entries(names).map(([kind,name])=>`<div class="connection">${icon(kind)}<div class="grow"><h2>${name}</h2><p>${({e2:'Import an IDrive E2 access-keys file and select an existing bucket/prefix. Keys stay server-side.',cloudgate:'Connect your own deployed cloudgate-wasmer client using its HTTPS URL and Basic credentials.',windows:'Download a one-use EXE, choose a local folder and run an outbound worker at Windows sign-in.',linux:'Install an outbound-only agent into a dedicated directory. One-time enrollment links expire in 15 minutes.'})[kind]}</p></div><span class="pill">${activeServers().filter(s=>s.kind===kind).length} servers</span></div>`).join('')}</div><div class="panel card"><h2>Agent enrollment address</h2><p class="subtitle">${esc(S.data.demo?'Automatic in an installed Burrow host; disabled in this demo.':S.data.publicUrl||S.data.agentRoute?.detail||'Burrow is preparing the HTTPS route automatically.')}</p><p class="form-hint">Managed automatically by Burrow. This dedicated public route exposes only /enroll.sh, /enroll.exe and /agent/*, not your dashboard or administration API. A command is issued only after an HTTPS health check succeeds. If setup is pending, check Burrow’s tunnel status and internet access; no manual URL setting is needed.</p></div>`}
function guideView(){return head('GET STARTED','A place for all your storage','Connect providers, publish a group and give each person the right access.')+`<section class="panel card">${[['Create a server group','Choose a group name and subdomain. Keep Use default Burrow tunnel checked to inherit your host’s existing domain and naming settings. Add the first storage user; its password must be at least 12 characters.'],['Connect a storage provider','IDrive E2 requires a keys-file upload and an existing bucket. For CloudGate, deploy your own client using its /setup helper; put secrets in Wasmer environment variables, not git. Linux requires Python 3. Burrow automatically creates and checks its HTTPS enrollment address; you do not have to enter a base URL.'],['Verify before you launch','For Linux, enter ~/storage or an absolute path, then press the small enter button to generate the one-time curl command. Run it on your server. Verification requires the storage probe and a real agent heartbeat.'],['Set quotas and directory permissions','Open a group, then use each server’s ⋯ menu. Partition budgets enforce logical directory quotas; no disk images or placeholder files are allocated. Rules can grant write, view-only or hidden access to specific paths.'],['Publish with Burrow','Default mode inherits Burrow’s active domain and naming without manual matching. Without a linked domain, Burrow can assign a temporary HTTPS address. Every server shares the group address; Uncheck the default option for the root domain directly. Unsupported root-level routing is reported explicitly; no prefixed fallback is used.'],['Move or erase safely','Delete Server stops new uploads. Move redistributes whole files according to your capacity shares, verifies the copy and checks that the source did not change before deletion. Erase requires a second confirmation and the exact server name. Failed work leaves the server draining.']].map(([title,text],i)=>`<div class="guide-step"><span class="step-num">${i+1}</span><div><h3>${title}</h3><p>${text}</p></div></div>`).join('')}<div class="notice warning">Preview-release limit: files up to 16 MiB; inventories up to 100,000 files. Back up your data before real-provider acceptance testing. Quotas cover writes through Robo Cloud, not independent changes made directly on a provider.</div></section>`}
function render(){if(!S.data)return;$('#group-count').textContent=S.data.groups.length;$('#release').textContent=S.data.version;$('#connection-pill').className='pill '+(S.data.demo?'demo':S.host?.connected?'good':'warn');$('#connection-pill').textContent=S.data.demo?'◌ Demo mode':S.host?.connected?'● Burrow connected':'○ Host offline';$$('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===S.nav));$('#breadcrumb').textContent=S.group?group(S.group)?.name:({groups:'Server groups',overview:'Storage overview',users:'Users & access',activity:'Activity log',connections:'Connections',guide:'Setup guide'})[S.nav];$('#content').innerHTML=S.group?groupView():({groups:renderGroups,overview:()=>head('WORKSPACE','Storage overview','Capacity and usage across every server group.')+demoNotice()+statistics()+S.data.groups.map(g=>`<div style="margin-bottom:20px">${groupCard(g)}</div>`).join(''),users:()=>head('ACCESS CONTROL','Users & access','Separate credentials and path-based access for every group.')+usersView(),activity:()=>head('WORKSPACE','Activity log','Operations, transfers and storage changes.')+activityView(),connections:connectionsView,guide:guideView})[S.nav]();}
async function refresh(paint=true){S.data=await api('api/state');try{S.host=await api('api/host')}catch(e){S.host={connected:false,note:e.message,domains:[]}}if(paint)render()}
function modal(title,description,body,foot){$('#modal').classList.remove('partition-dialog');$('#modal-content').innerHTML=`<div class="modal-head"><div class="grow"><h2>${title}</h2><p>${description}</p></div><button class="icon-btn" data-act="close-modal" aria-label="Close dialog">×</button></div><div class="modal-body">${body}<div id="modal-error" class="error" role="alert"></div></div><div class="modal-foot"><button class="btn ghost" data-act="close-modal">Cancel</button>${foot||''}</div>`;if(!$('#modal').open)$('#modal').showModal();setTimeout(()=>$('#modal input:not([type=hidden])')?.focus(),30)}
function field(label,name,value='',placeholder='',type='text',extra=''){return `<div class="field"><label class="form-label" for="f-${name}">${label}</label><input class="input" id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" placeholder="${esc(placeholder)}" ${extra}></div>`}
function readFields(){const out={};$$('#modal [name]').forEach(e=>{out[e.name]=e.type==='checkbox'?e.checked:e.value});return out}
function routeFields(g={}){const useDefault=g.useDefaultTunnel!==false,roots=S.host?.rootDomains||(S.host?.domains||[]).map(domain=>({domain,available:domain===S.host?.base}));const choices=useDefault?(S.host?.base?[{domain:S.host.base}]:[]):roots;const selected=useDefault?S.host?.base:(g.base||g.domain);return `<div class="route-fields"><div class="field"><label class="form-label">Group address</label><div class="field-row"><input class="input" name="sub" value="${esc(g.sub||'')}" placeholder="group-name" aria-label="Group subdomain" maxlength="40"><select name="base" aria-label="Group tunnel domain" ${useDefault?'disabled':''}>${choices.length?choices.map(d=>`<option value="${esc(d.domain)}" ${selected===d.domain?'selected':''}>${esc(d.domain)}</option>`).join(''):`<option value="">${useDefault?'Automatic HTTPS address':'No linked root domain'}</option>`}</select></div><label class="check"><input name="useDefaultTunnel" type="checkbox" ${useDefault?'checked':''}>Use default Burrow tunnel</label><p class="form-hint route-mode-note">${useDefault?`Uses Burrow’s configured naming${S.host?.base?' · '+esc(S.host.base):'; Burrow assigns a temporary HTTPS address when no domain is linked'}.`:'Uses the selected root domain directly, without Burrow’s prefix. If the host cannot serve it, Launch reports that limitation instead of substituting a prefixed address.'}</p></div></div>`}
function addGroup(){S.modal='group';modal('Add Server Group','One address. All the storage you need.',field('Group name','name','','e.g. Creative studio')+routeFields()+`<hr class="separator"><h3 style="margin-bottom:16px">First group user</h3><p class="form-hint" style="margin-bottom:15px">Storage links use the browser’s native sign-in dialog. You can add more users and restrict paths later.</p>`+field('Username','username','','e.g. studio-admin')+field('Password','password','','At least 12 characters','password','autocomplete="new-password" minlength="12"'),'<button class="btn primary" data-act="save-group">Create Group →</button>')}
function addServer(gid){S.providerDrafts={};S.modal='server';S.draft={group:gid,kind:'e2',name:'',limitValue:'',limitUnit:'GB',path:'~/robo-storage',keysFile:'',fileName:'',bucket:'',prefix:'',endpoint:'',username:'',password:'',category:'general',id:'',command:''};serverModal()}
function captureServer(){if(S.modal==='server')Object.assign(S.draft,readFields())}
function serverModal(){const d=S.draft,g=group(d.group);let provider='';if(d.kind==='e2'){provider=`<label class="upload-zone"><span>↥</span><strong>${d.fileName?esc(d.fileName):'Import your access-keys file'}</strong><small>Required · IDrive E2 text export · max 16 KB</small><input id="keys-upload" type="file" accept=".txt,text/plain" aria-label="IDrive E2 access keys file"></label><p class="form-hint" style="margin-bottom:18px">Credentials are stored privately on the server. The example you supplied is never bundled or used.</p>`+field('Bucket name','bucket',d.bucket,'Existing bucket')+field('Folder prefix (optional)','prefix',d.prefix,'e.g. studio');}else if(d.kind==='cloudgate'){provider=`<div class="info"><strong>Connect your deployed CloudGate client</strong><br>1. Deploy <a href="https://github.com/alexd-aero/cloudgate-wasmer" target="_blank" rel="noopener">cloudgate-wasmer ↗</a> to your own Wasmer account.<br>2. Use its <span class="mono">/setup</span> helper to get a CGSETUP1 code. Put CLOUDGATE_EMAIL, CLOUDGATE_REFRESH_TOKEN, CREDENTIALS and REAUTH_ACCESS_TOKEN in deployment environment variables.<br>3. Paste the client URL and the username/password set in CREDENTIALS below.<br><strong>The reauthentication key is not an API login key.</strong></div>`+field('Deployed client HTTPS URL','endpoint',d.endpoint,'https://your-client.wasmer.app')+`<div class="field-row equal">${field('Client username','username',d.username,'Username')}${field('Client password','password',d.password,'Password','password')}</div>`+field('Storage category','category',d.category,'general');}else if(d.kind==='windows'){const saved=d.id&&server(d.id);provider=`<div class="info" id="enrollment-route-status">${esc(agentRouteNote())}</div><p class="form-hint">Windows 10/11 x64 · Choose a local storage folder in the installer. No administrator rights or inbound port are required. The worker runs at your Windows sign-in.</p><button class="btn" data-act="generate-command" ${S.busy?'disabled':''}>Generate one-use Windows installer</button>${d.download?`<p class="form-hint">Expires in 15 minutes · Downloading does not use the installer. It is consumed only after a successful folder probe and registration.</p><a class="btn primary" href="${esc(d.download)}" download="Robo Cloud Enrollment.exe" target="_blank" rel="noopener noreferrer">Download Windows EXE ↓</a>`:''}<div class="verification ${saved?.verified?'good':''}" id="linux-verification">${saved?.verified?'✓ Verified':'× Not Verified'}</div><p class="form-hint">The installer uses standard Windows dialogs: Cancel / Continue, then a folder picker. This unsigned build may trigger Windows SmartScreen. A real probe and authenticated worker heartbeat are required before Launch.</p>`;}else{const saved=d.id&&server(d.id);provider=`<div class="info" id="enrollment-route-status">${esc(agentRouteNote())}</div><div class="field"><label class="form-label" for="linux-path">Storage directory</label><div class="enter-row"><input class="input mono" id="linux-path" name="path" value="${esc(d.path)}" placeholder="~/robo-storage or /mnt/storage" ${d.id?'readonly':''}><button class="enter-btn" data-act="generate-command" aria-label="Generate Linux enrollment command" ${S.busy?'disabled':''}>↵</button></div><p class="form-hint">~/ means the account running the command. / means an absolute path. The agent creates this directory if it does not exist.</p></div>${d.command?`<label class="form-label">Run on your Linux server · expires in 15 minutes</label><div class="command-block"><pre class="command" tabindex="0"><code>${esc(d.command)}</code></pre><button class="copy-command" data-act="copy-command" aria-label="Copy enrollment command" title="Copy command">${copyIcon()}</button><span class="copy-feedback" role="status" aria-live="polite"></span></div>`:''}<div class="verification ${saved?.verified?'good':''}" id="linux-verification">${saved?.verified?'✓ Verified':'× Not Verified'}</div><p class="form-hint">A real storage probe and agent heartbeat must complete before Launch is enabled. Python 3, curl and base64 are required. The agent opens no inbound port.</p>`;}
modal(d.reconnect?'Reconnect Server':'Add Server',`Connect storage to ${esc(g.name)}`,`<div class="provider-tabs" role="tablist">${Object.entries(names).map(([k,n])=>`<button class="provider-tab ${d.kind===k?'active':''}" data-act="provider-tab" data-kind="${k}" role="tab" aria-selected="${d.kind===k}" ${d.reconnect&&k!==d.kind?'disabled':''}><img src="assets/${k}.svg" alt="">${n}</button>`).join('')}</div>`+field('Server name','name',d.name,'e.g. Archive server')+provider+`<hr class="separator"><div class="field"><label class="form-label">Allocated storage maximum (optional)</label><div class="field-row"><input class="input" type="number" min="0" name="limitValue" value="${esc(d.limitValue)}" placeholder="No configured limit"><select name="limitUnit"><option ${d.limitUnit==='GB'?'selected':''}>GB</option><option ${d.limitUnit==='MB'?'selected':''}>MB</option></select></div><p class="form-hint">This is the maximum this server contributes to the group, not the physical disk size. Changes are saved before Launch, even after command generation. 0 or blank means unlimited; no disk space is reserved.</p></div>`+`<div class="info"><strong>Uses the group’s address</strong><br>${esc(address(g))}<br>All servers share the group’s tunnel. No separate domain or tunnel setup is needed here.</div>`,`<button class="btn primary" id="launch-server" data-act="launch-server" ${(d.kind==='e2'&&!d.keysFile)||(['linux','windows'].includes(d.kind)&&!server(d.id)?.verified)?'disabled':''}>Verify & Launch ↗</button>`)}
function settingsModal(id,tab='quota'){if(tab==='partitions'){openPartitionManager(id);return}const s=server(id);S.modal='settings';S.draft={id,tab};const value=s.limit?(s.limit/1e9):'';let body=`<div class="local-tabs">${['quota','partitions','danger'].map(t=>`<button data-act="settings-tab" data-tab="${t}" class="${t===tab?'active':''}">${({quota:'Usage & settings',partitions:'Partitions',danger:'Remove server'})[t]}</button>`).join('')}</div>`;let foot='';if(tab==='quota'){body+=field('Server name','name',s.name)+`<div class="field"><label class="form-label">Maximum storage</label><div class="field-row"><input class="input" type="number" min="0" step="any" name="limitValue" value="${value}" placeholder="No configured limit"><select name="limitUnit"><option>GB</option><option>MB</option></select></div><p class="form-hint">${fmt(s.used)} currently used. 0 or blank means no configured quota.</p></div>${['linux','windows'].includes(s.kind)?`<button class="btn" data-act="reenroll" data-id="${s.id}">Generate replacement ${s.kind==='windows'?'installer':'command'}…</button><p class="form-hint">Reconnect this server to the same storage folder. Successful registration rotates old worker credentials; existing data is not erased.</p>`:''}<label class="check"><input name="readOnly" type="checkbox" ${s.readOnly?'checked':''}>Read-only: prevent uploads and file deletion</label><div class="info">Quotas are enforced server-side on uploads through Robo Cloud. Direct changes on IDrive, CloudGate or Linux are discovered by Test. They cannot be blocked by this addon.</div>`;foot='<button class="btn primary" data-act="save-settings">Save settings</button>';}else if(['linux','windows'].includes(s.kind)&&!s.probeDone&&!s.verified&&!s.inventory.length){body+=`<div class="notice warning">This folder worker has never enrolled. Cancel its enrollment to revoke outstanding installer links and remove this pending entry. No remote files are contacted or deleted.</div><button class="btn danger" data-act="cancel-enrollment" data-id="${s.id}">Cancel unenrolled server…</button>`;}else{body+=`<div class="notice warning">Removal immediately stops new uploads. The server stays in the group until its data is safely moved or erased.</div><p class="subtitle">${esc(s.name)} contains ${fmt(s.used)} in ${s.inventory.length} files. Quotas and partitions are not changed while draining.</p><p class="subtitle">Copy conflicts, provider errors, oversized files or lost agents stop removal safely. You can retry after fixing the problem.</p><button class="btn danger" data-act="remove-dialog" data-id="${s.id}" style="margin-top:22px">Delete Server…</button>`;}
modal(esc(s.name),'Storage settings and directory budgets',body,foot)}
function userModal(gid,id){let u=id?S.data.users.find(u=>u.id===id):null;S.modal='user';S.draft={group:gid||u?.group||S.data.groups[0]?.id,id:id||'',rules:u?u.rules.map(r=>({...r})):[{path:'',access:'write'}]};paintUser(u)}
function paintUser(u){const d=S.draft;modal(u?'Manage user':'Add group user','Separate credentials. Precise permissions.',(!u?`<div class="field"><label class="form-label">Group</label><select name="group">${S.data.groups.map(g=>`<option value="${g.id}" ${d.group===g.id?'selected':''}>${esc(g.name)}</option>`).join('')}</select></div>`:'')+field('Username','username',u?.username||d.username||'','e.g. alex','text','')+field(u?'New password (leave blank to keep)':'Password','password','','At least 12 characters','password','autocomplete="new-password"')+`<label class="check"><input type="checkbox" name="enabled" ${u?.enabled===false?'':'checked'}>User enabled</label><hr class="separator"><div class="panel-title"><h3>Directory & file rules</h3><button class="text-btn" data-act="add-rule">＋ Add rule</button></div><div id="user-rules">${d.rules.map((r,i)=>ruleHTML(r,i)).join('')}</div><p class="form-hint">Blank path matches all files. A more specific path overrides a broader rule. “Hidden” denies both listing and access. Paths may identify individual files.</p><p class="password-note">Example: / → Write, finance → Hidden, public → View only. Passwords are hashed using scrypt. Native browser credentials may remain cached until the browser window is closed.</p>`,`<button class="btn primary" data-act="save-user">${u?'Save access':'Create user'}</button>`)}
function ruleHTML(r,i){return `<div class="rule" data-rule="${i}"><input class="input rule-path" value="${esc(r.path)}" placeholder="All paths (blank)" aria-label="Rule path"><select class="rule-access" aria-label="Access level">${[['write','Read & write'],['read','View only'],['none','Hidden']].map(([v,t])=>`<option value="${v}" ${r.access===v?'selected':''}>${t}</option>`).join('')}</select><button class="icon-btn" data-act="remove-rule" data-index="${i}" aria-label="Remove rule">×</button></div>`}
function rulesFromForm(){return $$('#user-rules .rule').map(r=>({path:r.querySelector('.rule-path').value,access:r.querySelector('.rule-access').value}))}
function removeModal(id){const s=server(id),targets=activeServers(s.group).filter(x=>x.id!==id&&x.verified&&x.status!=='draining');S.modal='remove';S.draft={id,targets:targets.map((t,i)=>({id:t.id,percent:Math.floor(100/Math.max(targets.length,1))+(i===0?100%Math.max(targets.length,1):0)}))};modal('Delete Server',`Safely disconnect ${esc(s.name)}`,`<div class="notice warning">Uploads stop when you confirm. This entry is kept until all its files are gone.</div><label class="check"><input type="checkbox" id="move-files" ${targets.length?'checked':''}>Move user files to other servers in this group</label><div id="move-options" ${targets.length?'':'hidden'}>${targets.length?'<p class="form-hint">Drag the segment boundaries or enter percentages. Whole files are assigned by byte-weighted share; a file is never split.</p><div class="range-bar" id="allocation-bar"></div><div class="range-labels" id="allocation-labels"></div>':'<p class="form-hint">No verified destinations. Add and verify another server first.</p>'}</div><div id="erase-warning" ${targets.length?'hidden':''}><div class="error">Without migration, continuing opens a second confirmation for permanent erasure of user files. This cannot be undone.</div></div>`, '<button class="btn danger" data-act="confirm-remove">Continue →</button>');drawAllocation()}
function drawAllocation(){const el=$('#allocation-bar');if(!el)return;el.innerHTML=S.draft.targets.map((t,i)=>`<div class="range-part" style="width:${t.percent}%"><strong>${esc(server(t.id).name)}</strong><span>${t.percent}%</span>${i<S.draft.targets.length-1?`<span class="resize-handle" data-handle="${i}"></span>`:''}</div>`).join('');$('#allocation-labels').innerHTML=S.draft.targets.map((t,i)=>`<label class="field-row"><span>${esc(server(t.id).name)}</span><input class="input allocation-input" type="number" min="1" max="100" value="${t.percent}" data-index="${i}" aria-label="${esc(server(t.id).name)} allocation percentage"></label>`).join('')}
function eraseConfirm(){const s=server(S.draft.id);S.modal='erase';modal('Permanently erase server data?','This is destructive and cannot be undone.',`<div class="error">You are permanently deleting user information and stored files within this server’s managed bucket prefix, CloudGate category or Linux directory. Its logical partitions will no longer be available.</div><p class="subtitle">The server is disconnected only after a fresh inventory confirms it is empty. A failure leaves it draining, not silently removed.</p>`+field(`Type “${esc(s.name)}” to confirm`,'confirmName','','Exact server name')+`<label class="check"><input name="understand" type="checkbox">I understand these files will be permanently erased.</label>`,'<button class="btn danger" data-act="erase-now">Erase & disconnect</button>')}
function bytes(fields){return Math.round(Number(fields.limitValue||0)*(fields.limitUnit==='MB'?1e6:1e9))}
async function ensureServer(){const d=S.draft;let result;if(d.id){result=await api(`api/servers/${d.id}/settings`,{name:d.name,limit:bytes(d)})}else{result=await api(`api/groups/${d.group}/servers`,{...d,limit:bytes(d)});d.id=result.server.id}await refresh(false);return server(d.id)}
async function action(el){const a=el.dataset.act,id=el.dataset.id;if(a==='close-modal'){$('#modal').close();S.modal=null;return}if(a==='add-group')return addGroup();if(a==='open-group'){S.group=id;S.tab='storage';render();return}if(a==='back'){S.group=null;render();return}if(a==='group-tab'){S.tab=el.dataset.tab;render();return}if(a==='add-server')return addServer(id);if(a==='provider-tab'){captureServer();const current=S.draft;S.providerDrafts[current.kind]={...current};const kind=el.dataset.kind;S.draft={group:current.group,name:current.name,limitValue:current.limitValue,limitUnit:current.limitUnit,kind,path:'~/robo-storage',category:'general',id:'',command:'',download:'',...(S.providerDrafts[kind]||{})};return serverModal()}if(a==='server-settings')return settingsModal(id);if(a==='reenroll'){const s=server(id);S.providerDrafts={};S.modal='server';S.draft={id:s.id,reconnect:true,group:s.group,kind:s.kind,name:s.name,path:s.path,limitValue:s.limit?s.limit/1e9:'',limitUnit:'GB',command:'',download:''};return serverModal()}if(a==='settings-tab')return settingsModal(S.draft.id,el.dataset.tab);if(a==='add-user'){if(!S.data.groups.length)return toast('Create a server group first.');return userModal(id)}if(a==='edit-user')return userModal(null,id);if(a==='remove-dialog')return removeModal(id);if(a==='add-rule'){S.draft.rules=rulesFromForm();S.draft.rules.push({path:'',access:'read'});$('#user-rules').innerHTML=S.draft.rules.map(ruleHTML).join('');return}if(a==='remove-rule'){S.draft.rules=rulesFromForm();S.draft.rules.splice(Number(el.dataset.index),1);$('#user-rules').innerHTML=S.draft.rules.map(ruleHTML).join('');return}if(a==='copy-command'){try{if(!navigator.clipboard)throw Error('Clipboard unavailable');await navigator.clipboard.writeText(S.draft.command);el.innerHTML=copyIcon(true);el.title='Copied!';el.setAttribute('aria-label','Command copied');$('.copy-feedback').textContent='Copied!';setTimeout(()=>{if(!el.isConnected)return;el.innerHTML=copyIcon();el.title='Copy command';el.setAttribute('aria-label','Copy enrollment command');$('.copy-feedback').textContent=''},2000)}catch{const pre=$('.command');if(pre){const range=document.createRange();range.selectNodeContents(pre);const selection=getSelection();selection.removeAllRanges();selection.addRange(range);pre.focus()}toast('Clipboard unavailable. The command is selected; press Ctrl+C to copy.')}return}
if(S.busy)return;S.busy=true;el.disabled=true;try{
if(a==='save-group'){const f=readFields();if(!f.username||f.password.length<12)throw Error('Choose a username and a password of at least 12 characters.');const r=await api('api/groups',f);await api(`api/groups/${r.group.id}/users`,{username:f.username,password:f.password,rules:[{path:'',access:'write'}],enabled:true});$('#modal').close();S.modal=null;await refresh();toast('Group created. Add your first storage server.');}
else if(a==='test'){toast('Testing connection and refreshing the real inventory…');await api(`api/servers/${id}/test`,{});await refresh();toast('Connection verified. Usage inventory updated.');}
else if(a==='generate-command'){captureServer();if(!S.draft.name)throw Error('Name this server before enrollment.');await ensureServer();const r=await api(`api/servers/${S.draft.id}/enrollment`,{});S.draft.command=r.command||'';S.draft.download=r.download||'';S.busy=false;serverModal();}
else if(a==='launch-server'){captureServer();if(S.draft.kind==='e2'&&!S.draft.keysFile)throw Error('Import an access-keys file first.');const s=await ensureServer();toast('Verifying storage before publishing…');await api(`api/servers/${s.id}/test`,{});const result=await api(`api/servers/${s.id}/launch`,{});$('#modal').close();S.modal=null;await refresh();toast(result.url?'Group HTTPS verified. Server is available at the group address.':'Group tunnel requested. Burrow is preparing and checking its HTTPS address.');}
else if(a==='launch-group'){const f={};$$('#content [name]').forEach(x=>f[x.name]=x.type==='checkbox'?x.checked:x.value);const r=await api(`api/groups/${id}/launch`,f);await refresh();toast(r.url?'Group HTTPS verified. Every server inherits this address.':'Burrow is preparing and checking the group’s HTTPS address. Status updates automatically.');}
else if(a==='cancel-enrollment'){const s=server(id);if(!confirm(`Cancel enrollment for ${s.name}? Outstanding installers will be revoked. No remote files will be changed.`))return;await api(`api/servers/${id}/cancel-enrollment`,{confirmName:s.name});$('#modal').close();S.modal=null;await refresh();toast('Unenrolled server cancelled. Remote files were not changed.');}
else if(a==='save-settings'){const f=readFields();await api(`api/servers/${S.draft.id}/settings`,{name:f.name,readOnly:f.readOnly,limit:bytes(f)});$('#modal').close();S.modal=null;await refresh();toast('Server settings saved.');}
else if(a==='save-user'){const f=readFields();await api(`api/groups/${f.group||S.draft.group}/users`,{id:S.draft.id||undefined,username:f.username,password:f.password,enabled:f.enabled,rules:rulesFromForm()});$('#modal').close();S.modal=null;await refresh();toast('User access saved.');}
else if(a==='confirm-remove'){if(!$('#move-files').checked){eraseConfirm();return}if(!S.draft.targets.length)throw Error('No verified destinations are available.');if(S.draft.targets.reduce((n,t)=>n+t.percent,0)!==100)throw Error('Destination shares must add up to 100%.');const s=server(S.draft.id);S.modal='move-confirm';modal('Move files & disconnect','Files are copied and verified before the source copy is removed.',`<div class="info">The source stops accepting uploads. Whole files are distributed to the selected destinations. Conflicts or failures leave the source draining.</div>`+field(`Type “${esc(s.name)}” to confirm`,'confirmName','','Exact server name'),'<button class="btn primary" data-act="move-now">Start verified migration</button>');}
else if(a==='move-now'){const f=readFields(),s=server(S.draft.id);await api(`api/servers/${s.id}/drain`,{mode:'move',targets:S.draft.targets,confirmName:f.confirmName});$('#modal').close();S.modal=null;S.group=s.group;S.tab='activity';await refresh();toast('Migration started. The source stays listed until it is empty.');}
else if(a==='erase-now'){const f=readFields();if(!f.understand)throw Error('Check the acknowledgment before permanently erasing files.');const s=server(S.draft.id);await api(`api/servers/${s.id}/drain`,{mode:'erase',confirmName:f.confirmName});$('#modal').close();S.modal=null;S.group=s.group;S.tab='activity';await refresh();toast('Erasure started. Failures keep this server draining.');}
}catch(e){const err=$('#modal-error');if($('#modal').open&&err)err.textContent=e.message;else toast(e.message)}finally{S.busy=false;if(el.isConnected)el.disabled=false}}
document.addEventListener('click',e=>{const nav=e.target.closest('[data-nav]');if(nav){S.nav=nav.dataset.nav;S.group=null;render();return}const el=e.target.closest('[data-act]');if(el)action(el)});
document.addEventListener('input',e=>{if(e.target.id==='group-search'){S.search=e.target.value;$('#group-grid').innerHTML=groupCards()}if(e.target.classList.contains('allocation-input')){S.draft.targets[Number(e.target.dataset.index)].percent=Math.min(100,Math.max(0,Number(e.target.value)||0));const bar=$('#allocation-bar');if(bar)bar.innerHTML=S.draft.targets.map((t,i)=>`<div class="range-part" style="width:${t.percent}%"><strong>${esc(server(t.id).name)}</strong><span>${t.percent}%</span>${i<S.draft.targets.length-1?`<span class="resize-handle" data-handle="${i}"></span>`:''}</div>`).join('')}});
document.addEventListener('change',async e=>{if(e.target.name==='useDefaultTunnel'){const root=e.target.closest('.route-fields'),sub=root.querySelector('[name=sub]').value,base=root.querySelector('[name=base]').value;root.outerHTML=routeFields({sub,base,useDefaultTunnel:e.target.checked});}if(e.target.id==='keys-upload'){const f=e.target.files[0];if(!f)return;if(f.size>16384){toast('The access-keys file must be no larger than 16 KB.');return}captureServer();S.draft.keysFile=await f.text();S.draft.fileName=f.name;serverModal()}if(e.target.id==='move-files'){$('#move-options').hidden=!e.target.checked;$('#erase-warning').hidden=e.target.checked}});
document.addEventListener('pointerdown',e=>{const handle=e.target.closest('[data-handle]');if(!handle)return;const i=Number(handle.dataset.handle),bar=$('#allocation-bar'),start=e.clientX,left=S.draft.targets[i].percent,right=S.draft.targets[i+1].percent;const move=event=>{const change=Math.round((event.clientX-start)/bar.clientWidth*100);const next=Math.max(1,Math.min(left+right-1,left+change));S.draft.targets[i].percent=next;S.draft.targets[i+1].percent=left+right-next;drawAllocation()};const up=()=>{document.removeEventListener('pointermove',move);document.removeEventListener('pointerup',up)};document.addEventListener('pointermove',move);document.addEventListener('pointerup',up)});
$('#modal').addEventListener('cancel',()=>{S.modal=null});$('#refresh').onclick=()=>refresh().then(()=>toast('Workspace refreshed.')).catch(e=>toast(e.message));
refresh().catch(e=>{$('#content').innerHTML=`<div class="error">${esc(e.message)}</div>`});
setInterval(async()=>{if(S.busy||!S.data)return;try{const latest=await api('api/state');S.data=latest;const routeNotice=$('#enrollment-route-status');if(routeNotice)routeNotice.textContent=agentRouteNote();if(S.modal==='server'&&['linux','windows'].includes(S.draft.kind)&&S.draft.id){const s=server(S.draft.id),v=$('#linux-verification');if(v){v.className='verification '+(s?.verified?'good':'');v.textContent=s?.verified?'✓ Verified':'× Not Verified';$('#launch-server').disabled=!s?.verified}}else if(!$('#modal').open){if(S.nav==='groups'&&!S.group){const grid=$('#group-grid');if(grid)grid.innerHTML=groupCards()}else if(S.group&&S.tab==='routing'){const g=group(S.group),badge=$('#route-live-badge');if(badge){badge.textContent=g.routeState==='ready'?'HTTPS verified':g.routeState==='blocked'?'Root unavailable':'Checking route';badge.className='pill '+(g.routeState==='ready'?'good':'');$('#route-live-detail').textContent=g.routeDetail||'';$('#route-live-address').innerHTML=g.url?`<p class="subtitle"><a href="${esc(g.url)}" target="_blank" rel="noopener">${esc(g.url)} ↗</a></p>`:''}}else if((S.group&&['activity','storage'].includes(S.tab))||S.nav==='connections')render()}}catch{}},5000);

document.addEventListener('keydown',e=>{const tab=e.target.closest('[role="tab"]');if(!tab||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;const tabs=[...tab.closest('[role="tablist"]').querySelectorAll('[role="tab"]')].filter(t=>!t.disabled);const n=e.key==='Home'?0:e.key==='End'?tabs.length-1:(tabs.indexOf(tab)+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;e.preventDefault();const chosen=tabs[n].dataset,selector=chosen.kind?`[role="tab"][data-kind="${chosen.kind}"]`:`[role="tab"][data-tab="${chosen.tab}"]`;tabs[n].click();document.querySelector(selector)?.focus()});
